\begin{abstract}
We develop harmonic analysis on finite abelian groups as a statement about \emph{structure} rather than about formulas. Working in the category $\FinAb$ of finite abelian groups and group homomorphisms, we realise the Pontryagin dual $G \mapsto \dual{G} = \Hom(G,\C^\times)$ as a functor and prove that it is an equivalence $\FinAb \simeq \FinAb^{\mathrm{op}}$, with unit the evaluation map into the double dual. The Fourier transform is then not a formula but a \emph{natural isomorphism} between two functors $\FinAb \to \mathsf{Mod}_\C$: the group-algebra functor (with pushforward along fibres) and the dual-functions functor (with restriction along dual maps). Naturality is the identity $\widehat{\varphi_*f} = \dual{f}\circ\dual{\varphi}$; invertibility is Fourier inversion. From this platform we obtain the convolution theorem, Plancherel's identity, the fourth-power identity $\mathcal{F}^4 = |G|^2\cdot\mathrm{id}$, exactness of duality with the character extension theorem and the annihilator count $|K^\perp||K| = |G|$, and Poisson summation. We prove the Donoho--Stark uncertainty principle $|\supp f|\cdot|\supp\dual f| \ge |G|$ together with a complete classification of its equality case: the extremals are exactly the modulated coset indicators; a corollary invisible from the inequality is that equality forces $|\supp f|$ to divide $|G|$. At the opposite extreme we evaluate the quadratic Gauss sum, $|\sum_x\psi(x^2)|^2 = N$ for odd $N$ and primitive $\psi$, and deduce that the quadratic phase realises the maximal uncertainty product $N^2$. Two principal results are structural: a \emph{kernel-level uncertainty principle}, valid for an arbitrary bounded analysis kernel with a bounded synthesis kernel and with an optimal constant governed by coherence rather than group order; and the identification of Pontryagin duality as a \emph{self-adjunction} whose hom-set bijection is the bicharacter swap, the Fourier kernel being the image of the identity morphism. A companion bridge theorem in enumerative combinatorics shows that the logarithmic-derivative form of the P\'olya tree functional equation is \emph{equivalent} to the divisor-weighted counting recurrence.
\end{abstract}

\noindent\textbf{Keywords:} Pontryagin duality, finite abelian groups, natural transformation, self-adjoint functor, Donoho--Stark uncertainty principle, mutual coherence, Gauss sums, P\'olya trees.

\section{Introduction}

The Fourier transform on a finite abelian group $G$ is usually introduced as the sum
\[
\dual f(\psi) = \sum_{g\in G} f(g)\,\psi(-g), \qquad \psi\in\dual G,
\]
with an inversion formula and a list of identities. This presentation obscures the fact that essentially every property in the list follows from two structural facts: the passage $G\mapsto\dual G$ is a \emph{functor}, and this functor is an \emph{equivalence}. We make that reduction explicit and then push past it. Three questions organise the paper.

\begin{enumerate}
\item \textbf{What is functorial about the Fourier transform?} It is a natural isomorphism between two functors from $\FinAb$ to complex vector spaces; its naturality square is the aliasing identity and its invertibility is Fourier inversion (Section~\ref{sec:transform}).
\item \textbf{What is the uncertainty principle about?} Not the Fourier transform: it is a statement about any bounded kernel with a bounded inverse, and the classical constant $|G|$ is a reciprocal coherence product (Section~\ref{sec:abstract}).
\item \textbf{Why the exponential kernel?} Because the dual functor is self-adjoint and the Fourier kernel is the image of the identity morphism under its hom-set bijection (Section~\ref{sec:self}).
\end{enumerate}

Throughout, $G,H$ are finite abelian groups written additively; $\dual G$ is the group of characters $\psi\colon G\to\C$ with $\psi(0)=1$ and $\psi(g+h)=\psi(g)\psi(h)$; $\supp f = \{g: f(g)\ne0\}$; and $\C[G]$ is the space of all functions $G\to\C$. Characters take values in roots of unity, so $|\psi(g)|=1$ and $\overline{\psi(g)}=\psi(-g)$.

\section{The category \texorpdfstring{$\FinAb$}{FinAb} and the dual functor}

\begin{definition}
$\FinAb$ is the category whose objects are finite abelian groups and whose morphisms are additive group homomorphisms.
\end{definition}

\begin{definition}
For $\varphi\colon G\to H$ define $\dual\varphi\colon\dual H\to\dual G$ by $\dual\varphi(\psi)=\psi\circ\varphi$.
\end{definition}

\begin{proposition}[Functoriality]
$\widehat{\mathrm{id}_G}=\mathrm{id}_{\dual G}$ and $\widehat{\psi\circ\varphi}=\dual\varphi\circ\dual\psi$. Hence $D\colon\FinAb^{\mathrm{op}}\to\FinAb$, $D(G)=\dual G$, $D(\varphi)=\dual\varphi$, is a functor: the \emph{Pontryagin dual functor}.
\end{proposition}

\begin{proof}[Proof sketch]
Both identities hold pointwise on characters and, evaluating further, pointwise on group elements; each is an instance of associativity of composition.
\end{proof}

\begin{lemma}[Counting characters]\label{lem:count}
$|\dual G| = |G|$ for every finite abelian $G$.
\end{lemma}

\begin{proof}[Proof sketch]
Reduce to $G=\Z/N$ by the structure theorem, where characters are $x\mapsto\zeta^{kx}$ for a primitive $N$-th root of unity $\zeta$ and $0\le k<N$; duality turns finite direct sums into finite direct products.
\end{proof}

\section{Pontryagin duality as an equivalence of categories}

\begin{definition}
For $g\in G$ let $\ev_g\in\widehat{\dual G}$ be $\ev_g(\psi)=\psi(g)$; the map $E_G\colon G\to\widehat{\dual G}$, $g\mapsto\ev_g$, is a homomorphism.
\end{definition}

\begin{theorem}[Pontryagin duality]\label{thm:pontryagin}
$E_G$ is an isomorphism for every finite abelian $G$, and $(E_G)_G$ is a natural isomorphism $\mathrm{id}_{\FinAb}\Rightarrow D^{\mathrm{op}}\circ D$. Together with the corresponding counit this exhibits an equivalence of categories
\[
\FinAb \;\simeq\; \FinAb^{\mathrm{op}},
\]
whose functor is the dual functor and whose unit is $E$.
\end{theorem}

\begin{proof}[Proof sketch]
Injectivity of $E_G$ is separation of points by characters: if $g\ne0$ there is $\psi$ with $\psi(g)\ne1$. Surjectivity follows by counting with Lemma~\ref{lem:count} applied twice. Naturality unwinds to $\psi(\varphi(g))=(\psi\circ\varphi)(g)$, and the triangle identity is verified pointwise in the same way.
\end{proof}

\begin{corollary}
Duality is essentially surjective: every finite abelian group is the character group of a finite abelian group, namely of its own dual.
\end{corollary}

\begin{corollary}
Duality is full: every homomorphism $u\colon\dual H\to\dual G$ equals $\dual\varphi$ for a unique $\varphi\colon G\to H$.
\end{corollary}

\begin{corollary}
For $\varphi\colon G\to H$ one has $\widehat{\dual\varphi} = E_H\circ\varphi\circ E_G^{-1}$.
\end{corollary}

\section{The Fourier transform as a natural isomorphism}\label{sec:transform}

\begin{definition}[Group-algebra functor]
$\mathcal{A}(G)=\C[G]$, and for $\varphi\colon G\to H$ the pushforward $(\varphi_*f)(h)=\sum_{\varphi(g)=h}f(g)$.
\end{definition}

\begin{definition}[Dual-functions functor]
$\mathcal{B}(G)=\C[\dual G]$, and for $\varphi\colon G\to H$ the map $F\mapsto F\circ\dual\varphi$.
\end{definition}

\begin{definition}
For $f\in\C[G]$ and $F\in\C[\dual G]$,
\[
\mathcal{F}_G(f)(\psi)=\sum_{g\in G}f(g)\psi(-g),\qquad
\mathcal{F}^{-1}_G(F)(g)=\frac1{|G|}\sum_{\psi\in\dual G}F(\psi)\psi(g).
\]
\end{definition}

\begin{lemma}[Orthogonality]\label{lem:orth}
For $x\in G$, $\sum_{\psi\in\dual G}\psi(x)=|G|\,[x=0]$; for $\psi\in\dual G$, $\sum_{g\in G}\psi(g)=|G|\,[\psi=1]$.
\end{lemma}

\begin{proof}[Proof sketch]
If $x\ne0$ choose $\chi$ with $\chi(x)\ne1$; the substitution $\psi\mapsto\chi\psi$ permutes $\dual G$ and multiplies the sum by $\chi(x)$, forcing it to vanish. The second relation is the same argument with the roles of $G$ and $\dual G$ exchanged via $E_G$.
\end{proof}

\begin{theorem}[Fourier inversion]\label{thm:inv}
$\mathcal{F}^{-1}_G\circ\mathcal{F}_G=\mathrm{id}$ and $\mathcal{F}_G\circ\mathcal{F}^{-1}_G=\mathrm{id}$.
\end{theorem}

\begin{proof}[Proof sketch]
$\mathcal{F}^{-1}(\mathcal{F}f)(x)=\frac1{|G|}\sum_g f(g)\sum_\psi\psi(x-g)=f(x)$ by Lemma~\ref{lem:orth}; the other composite is symmetric.
\end{proof}

\begin{theorem}[Naturality]\label{thm:nat}
For every $\varphi\colon G\to H$, every $f\in\C[G]$ and every $\psi\in\dual H$,
\[
\widehat{\varphi_*f}(\psi) \;=\; \dual f\bigl(\dual\varphi(\psi)\bigr) \;=\; \dual f(\psi\circ\varphi).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Write the left side as $\sum_h\bigl(\sum_{\varphi(g)=h}f(g)\bigr)\psi(-h)$ and interchange the sums; the fibre condition collapses the $h$-sum to $h=\varphi(g)$.
\end{proof}

\begin{theorem}[Fourier analysis is a natural isomorphism]
The family $(\mathcal{F}_G)_G$ is a natural isomorphism $\mathcal{A}\cong\mathcal{B}$ of functors $\FinAb\to\mathsf{Mod}_\C$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:nat} is the naturality square; Theorem~\ref{thm:inv} gives invertibility of each component.
\end{proof}

\begin{remark}
Downsampling and aliasing identities are Theorem~\ref{thm:nat} for surjective $\varphi$; periodisation identities are Theorem~\ref{thm:nat} for a quotient map $G\to G/K$.
\end{remark}

\section{Convolution, Plancherel, and the fourth power}

\begin{definition}
$(f*g)(x)=\sum_{y\in G}f(y)g(x-y)$.
\end{definition}

\begin{theorem}[Convolution theorem]
$\widehat{f*g}=\dual f\cdot\dual g$ pointwise. Consequently $*$ is commutative and associative, distributes over addition, and has $\delta_0$ as unit.
\end{theorem}

\begin{proof}[Proof sketch]
Substituting $x=y+z$ and factoring $\psi(-y-z)=\psi(-y)\psi(-z)$ splits the double sum; the algebraic corollaries transport through the injective map $\mathcal{F}$.
\end{proof}

\begin{theorem}[Plancherel]
$\displaystyle\sum_{\psi\in\dual G}|\dual f(\psi)|^2 = |G|\sum_{g\in G}|f(g)|^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Expand $\dual f(\psi)\overline{\dual f(\psi)}=\sum_{g,h}f(g)\overline{f(h)}\psi(h-g)$, sum over $\psi$ and apply Lemma~\ref{lem:orth} to kill the terms with $g\ne h$.
\end{proof}

\begin{theorem}[Fourth-power identity]
$\widehat{\dual f}(E_Gx)=|G|f(-x)$; after two double-dual identifications, $\mathcal{F}^4=|G|^2\cdot\mathrm{id}$.
\end{theorem}

\begin{proof}[Proof sketch]
$\widehat{\dual f}(E_Gx)=\sum_\psi\dual f(\psi)\psi(-x)=|G|f(-x)$ by inversion at $-x$; iterate and use $|\widehat{\dual G}|=|G|$.
\end{proof}

\section{Exactness, annihilators, and Poisson summation}

\begin{theorem}[Exactness]\label{thm:exact}
If $\varphi\colon H\to G$ is injective then $\dual\varphi$ is surjective; if $\varphi$ is surjective then $\dual\varphi$ is injective.
\end{theorem}

\begin{proof}[Proof sketch]
An equivalence of categories preserves monomorphisms and epimorphisms and reverses them along $\mathrm{op}$; in $\FinAb$, mono means injective and epi means surjective.
\end{proof}

\begin{corollary}[Character extension]\label{cor:ext}
Every character of a subgroup $K\le G$ extends to a character of $G$.
\end{corollary}

\begin{definition}
$K^\perp=\{\psi\in\dual G:\psi|_K\equiv1\}$, the kernel of restriction $\dual G\to\dual K$.
\end{definition}

\begin{theorem}[Annihilator counting]\label{thm:ann}
$|K^\perp|\cdot|K| = |G|$.
\end{theorem}

\begin{proof}[Proof sketch]
Restriction is surjective by Corollary~\ref{cor:ext} with kernel $K^\perp$, so $|\dual G|=|\dual K|\cdot|K^\perp|$; apply Lemma~\ref{lem:count} to $G$ and to $K$.
\end{proof}

\begin{lemma}\label{lem:annsum}
$\sum_{\psi\in K^\perp}\psi(x)=|K^\perp|\,[x\in K]$.
\end{lemma}

\begin{theorem}[Poisson summation]
For every subgroup $K\le G$ and every $f\in\C[G]$,
\[
|G|\sum_{k\in K}f(k) \;=\; |K|\sum_{\psi\in K^\perp}\dual f(\psi).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Expand the right-hand sum, exchange the order of summation and apply Lemma~\ref{lem:annsum} at $x=-g$, obtaining $|K^\perp|\sum_{g\in K}f(g)$; then use Theorem~\ref{thm:ann}.
\end{proof}

\section{The uncertainty principle and its equality case}

\begin{theorem}[Donoho--Stark]\label{thm:ds}
For every non-zero $f\in\C[G]$, \quad $|\supp f|\cdot|\supp\dual f| \ge |G|$.
\end{theorem}

\begin{proof}
Let $M=\max_g|f(g)|>0$, attained at $g_0$. For every $\psi$, $|\dual f(\psi)| \le \sum_{g\in\supp f}|f(g)| \le |\supp f|\,M$. Inversion at $g_0$ involves only characters in $\supp\dual f$, so $M \le |G|^{-1}|\supp\dual f|\,|\supp f|\,M$. Divide by $M>0$.
\end{proof}

\begin{corollary}
$|\supp f|+|\supp\dual f|\ge2\sqrt{|G|}$, hence $\max(|\supp f|,|\supp\dual f|)\ge\sqrt{|G|}$.
\end{corollary}

\begin{corollary}
If $|\supp f|\cdot|\supp\dual f|<|G|$ then $f=0$; in particular a function supported at one point has a nowhere-vanishing transform.
\end{corollary}

\begin{theorem}[Sharpness]
For a Dirac mass, $\widehat{\delta_a}(\psi)=\psi(-a)$ never vanishes, so $|\supp\delta_a|\cdot|\supp\widehat{\delta_a}| = |G|$.
\end{theorem}

For $K\le G$, $a\in G$, $\chi\in\dual G$ set $c_{K,a,\chi}(g)=\chi(g)$ if $g-a\in K$ and $0$ otherwise.

\begin{theorem}[Coset indicators are extremal]\label{thm:coset}
$|\supp c_{K,a,\chi}| = |K|$ and $|\supp\widehat{c_{K,a,\chi}}| = |K^\perp| = |G|/|K|$, so equality holds in Theorem~\ref{thm:ds}.
\end{theorem}

\begin{proof}[Proof sketch]
Use $\sum_{k\in K}\psi(k)=|K|[\psi\in K^\perp]$ to compute the transform; its support is the coset $\chi K^\perp$, of size $|K^\perp|$. Apply Theorem~\ref{thm:ann}.
\end{proof}

\begin{theorem}[Rigidity: complete classification of the extremals]\label{thm:rigid}
Let $f\ne0$. Then $|\supp f|\cdot|\supp\dual f| = |G|$ if and only if there exist a subgroup $K\le G$, a point $a\in G$, a character $\chi\in\dual G$ and a scalar $c\ne0$ with
\[
f(g)=\begin{cases} c\,\chi(g), & g-a\in K,\\ 0,&\text{otherwise.}\end{cases}
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) Theorem~\ref{thm:coset}, since scaling by $c\ne0$ does not change supports.

($\Rightarrow$) Equality forces every estimate in the proof of Theorem~\ref{thm:ds} to be tight. First, $|\dual f(\psi)| = M|\supp f|$ for all $\psi\in\supp\dual f$, so the triangle inequality $|\sum_{g\in\supp f}f(g)\psi(-g)|\le\sum|f(g)|$ is an equality; this forces all summands to share a phase and all $|f(g)|$ to equal $M$ on the support, whence $f = c\,\chi$ on $\supp f$ for a scalar $c$ with $|c|=M$ and a character $\chi$ --- phase alignment transported across the support is exactly multiplicativity. Second, the set of $x$ such that $f(\cdot+x)$ is a unimodular multiple of $f$ is a subgroup $K$, and tightness forces $\supp f$ to be a single coset $a+K$.
\end{proof}

\begin{theorem}[Divisibility obstruction]\label{thm:div}
If $f\ne0$ attains equality in Theorem~\ref{thm:ds} then $|\supp f|$ divides $|G|$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:rigid} the support is a coset of a subgroup $K$, so $|\supp f|=|K|$; apply Lagrange's theorem.
\end{proof}

\begin{corollary}[Strict uncertainty]
If $|\supp f|\nmid|G|$ then $|\supp f|\cdot|\supp\dual f| > |G|$ strictly.
\end{corollary}

\begin{remark}
For $G=\Z/p$ with $p$ prime this yields a dichotomy: every non-zero $f$ with $1<|\supp f|<p$ has strictly super-critical uncertainty product, which underlies exact recovery of sparse signals from few frequency samples.
\end{remark}

\section{The kernel-level uncertainty principle}\label{sec:abstract}

The proof of Theorem~\ref{thm:ds} used only $|\psi(-g)|\le1$, the inversion identity, and $||G|^{-1}\psi(g)|\le|G|^{-1}$. Abstracting them gives the following.

\begin{definition}
For finite sets $G,H$ and $k\colon G\times H\to\C$, put $(T_kf)(h)=\sum_{g\in G}f(g)k(g,h)$.
\end{definition}

\begin{theorem}[Kernel uncertainty principle]\label{thm:abs}
Let $|k(g,h)|\le\mu$ for all $g,h$, and let $l\colon H\times G\to\C$ satisfy $|l(h,g)|\le\nu$ and
\[
f(g)=\sum_{h\in H}(T_kf)(h)\,l(h,g) \qquad\text{for all } f,g .
\]
Then for every $f\ne0$,
\[
1 \;\le\; \mu\,\nu\,|\supp f|\cdot|\supp T_kf| .
\]
\end{theorem}

\begin{proof}
Let $M=\max_g|f(g)|>0$, attained at $g_0$. For each $h$, $|(T_kf)(h)|\le\sum_{g\in\supp f}|f(g)||k(g,h)| \le |\supp f|M\mu$. Applying the reconstruction identity at $g_0$, only $h\in\supp T_kf$ contribute, so $M\le|\supp T_kf|\cdot|\supp f|M\mu\cdot\nu$. Cancel $M>0$.
\end{proof}

No linearity beyond the definition of $T_k$, no orthogonality, no unitarity, and no group structure is used.

\begin{corollary}[Donoho--Stark recovered]
With $H=\dual G$, $k(g,\psi)=\psi(-g)$ and $l(\psi,g)=|G|^{-1}\psi(g)$ one has $\mu=1$ and $\nu=|G|^{-1}$, and Theorem~\ref{thm:abs} becomes Theorem~\ref{thm:ds}.
\end{corollary}

Thus the constant $|G|$ enters only through the normalisation of the inversion kernel: the governing invariant is the coherence product $\mu\nu$.

\begin{corollary}[Elad--Bruckstein coherence bound]\label{cor:eb}
Let $U\colon G\times H\to\C$ have orthonormal rows, $\sum_h U(g,h)\overline{U(g',h)}=[g=g']$, with entries of modulus at most $\mu$. Then $1\le\mu^2|\supp f|\cdot|\supp T_Uf|$ for every $f\ne0$.
\end{corollary}

\begin{proof}[Proof sketch]
Orthonormality of rows makes $l(h,g)=\overline{U(g,h)}$ a reconstruction kernel; apply Theorem~\ref{thm:abs} with $\nu=\mu$.
\end{proof}

\begin{corollary}[Mutually unbiased / complex Hadamard form]
If in addition all entries have modulus at most $1/\sqrt n$, then $n\le|\supp f|\cdot|\supp T_Uf|$.
\end{corollary}

\begin{example}[A group-free witness]
For $H_2=\tfrac1{\sqrt2}\left(\begin{smallmatrix}1&1\\1&-1\end{smallmatrix}\right)$ we get $|\supp f|\cdot|\supp H_2f|\ge2$ for every non-zero $f\in\C^2$: no vector is a single coordinate in both the standard and the Hadamard basis.
\end{example}

\begin{theorem}[Optimality of the constant]
If the kernel is flat, $|k(g,h)|=\mu>0$ for all $g,h$, then $T_k\delta_a = k(a,\cdot)$ is nowhere zero, so $|\supp\delta_a|\cdot|\supp T_k\delta_a| = |H|$ and Theorem~\ref{thm:abs} forces $1\le\mu\nu|H|$. Hence $(\mu\nu)^{-1}$ cannot be improved.
\end{theorem}

Flatness is therefore the precise mechanism behind sharpness: the character table is a flat matrix.

\section{The opposite extreme: quadratic Gauss sums}

Let $N$ be odd and $\psi$ a primitive additive character of $\Z/N$ (that is, $x\mapsto\psi(ax)$ is non-trivial for every $a\ne0$). Set $q_\psi(x)=\psi(x^2)$.

\begin{theorem}[Gauss sum evaluation]\label{thm:gauss}
$\displaystyle\Bigl|\sum_{x\in\Z/N}\psi(x^2)\Bigr|^2 = N$.
\end{theorem}

\begin{proof}[Proof sketch]
With $S=\sum_x\psi(x^2)$, substituting $x=y+t$ gives $S\overline S=\sum_t\psi(t^2)\sum_y\psi(2ty)$. Since $N$ is odd, $2$ is a unit, so $2t=0$ only for $t=0$; for $t\ne0$ the inner sum is a complete sum of a non-trivial character and vanishes by Lemma~\ref{lem:orth}. Only $t=0$ survives, contributing $N$.
\end{proof}

\begin{theorem}[Flatness of the quadratic phase]
$|\widehat{q_\psi}(\chi)|^2 = N$ for every character $\chi$; in particular $\widehat{q_\psi}$ never vanishes.
\end{theorem}

\begin{proof}[Proof sketch]
Primitivity makes every $\chi$ a shift $x\mapsto\psi(bx)$; then $q_\psi(x)\chi(-x)=\psi(x^2-bx)$ and completing the square reduces to Theorem~\ref{thm:gauss}.
\end{proof}

\begin{theorem}[Maximal uncertainty product]
For odd $N>1$ and primitive $\psi$, $|\supp q_\psi|\cdot|\supp\widehat{q_\psi}| = N^2 > N$: the quadratic phase is anti-extremal.
\end{theorem}

\section{Duality as a self-adjunction}\label{sec:self}

\begin{definition}
For a homomorphism $f\colon G\to\dual H$, define $\sigma(f)\colon H\to\dual G$ by $\sigma(f)(h)(g)=f(g)(h)$.
\end{definition}

\begin{proposition}[Bicharacter swap]\label{prop:swap}
$\sigma(f)$ is a homomorphism, $\sigma\circ\sigma=\mathrm{id}$, and $\sigma$ is additive; hence
\[
\sigma\colon\Hom(G,\dual H)\;\xrightarrow{\ \cong\ }\;\Hom(H,\dual G)
\]
is an involutive isomorphism of abelian groups, natural in both variables:
$\sigma(f\circ\varphi)=\dual\varphi\circ\sigma(f)$ and $\sigma(\dual\varphi\circ f)=\sigma(f)\circ\varphi$.
\end{proposition}

\begin{corollary}
$|\Hom(G,\dual H)| = |\Hom(H,\dual G)|$: bicharacters of $G\times H$ may be counted on either side.
\end{corollary}

\begin{theorem}[Self-adjunction]
The dual functor is adjoint to itself in the sense appropriate to a contravariant functor: the equivalence of Theorem~\ref{thm:pontryagin} is an adjunction $D^{\mathrm{op}}\dashv D$ whose unit is the double-duality isomorphism $E$. Moreover its abstract hom-set bijection is exactly the swap $\sigma$ of Proposition~\ref{prop:swap}.
\end{theorem}

\begin{proof}[Proof sketch]
An equivalence gives an adjunction with unit its unit isomorphism, here $E$. The abstract adjunct is computed as $u\mapsto D(u)\circ\text{unit}$; evaluating at $g$ and then at $h$ gives $u(h)(g)$, which is the defining formula for $\sigma$.
\end{proof}

\begin{theorem}[The Fourier kernel is the swap of the identity]
Let $E=\sigma(\mathrm{id}_{\dual G})\colon G\to\widehat{\dual G}$. Then $E$ is the evaluation map, and for all $f\in\C[G]$, $\psi\in\dual G$,
\[
\dual f(\psi)=\sum_{g\in G}f(g)\,E(-g)(\psi).
\]
\end{theorem}

\begin{proof}
$\mathrm{id}_{\dual G}$ is a bicharacter of $\dual G\times G$; swapping gives $\sigma(\mathrm{id})(g)(\psi)=\psi(g)$, i.e.\ $\ev_g$. Hence $E(-g)(\psi)=\psi(-g)$.
\end{proof}

The exponential kernel is therefore not a choice: it is the image of the identity morphism under a canonical, natural, involutive bijection. Any category self-dual in this sense carries a Fourier transform whose kernel is determined.

\section{Algorithms}

\paragraph{Character-table transform.} For $G=\Z/N$ the transform is the DFT matrix, costing $O(N^2)$ naively and $O(N\log N)$ by the Cooley--Tukey factorisation. The latter is an instance of Theorem~\ref{thm:nat}: for $N=N_1N_2$, the exact sequence $\Z/N_1\hookrightarrow\Z/N\twoheadrightarrow\Z/N_2$ makes the transform factor through pushforward along the quotient, which is precisely ``decimate, transform, twiddle, transform''.

\paragraph{Certifying extremality.} Computing $\dual f$ and the two support sizes decides extremality for Theorem~\ref{thm:ds} in $O(N\log N)$. Theorem~\ref{thm:div} gives a cheaper one-sided certificate: if $|\supp f|\nmid|G|$, extremality is impossible, with no transform required --- an $O(N)$ test.

\section{A companion bridge: P\'olya trees}

The Fourier development above instantiates a general pattern: an identity converting a structural description into a computational recurrence, together with the observation that the conversion is reversible. We record an independent instance.

Let $a_k$ be the number of rooted unlabelled trees on $k$ nodes: $1,1,2,4,9,20,48,115,286,719,1842,4766,\dots$. Its generating function $A(z)=\sum_{k\ge1}a_kz^k$ satisfies
\begin{equation}\tag{FE}
A(z)=z\exp\Bigl(\sum_{i\ge1}\frac{A(z^i)}{i}\Bigr)=z\exp(S(z)),\qquad S(z):=\sum_{i\ge1}\frac{A(z^i)}{i},
\end{equation}
reflecting that a tree is a root with an unordered multiset of subtrees. Logarithmic differentiation removes the exponential:
\begin{equation}\tag{LD}
z\,A'(z)=A(z)\bigl(1+z\,S'(z)\bigr),
\end{equation}
which is equivalent to (FE) given $a_1=1$.

\begin{definition}
For $a\colon\N\to\Q$ set $\omega_n=\sum_{d\mid n}d\,a_d$ and $s_n=\sum_{i\mid n}a_{n/i}/i$. Here $s_n=[z^n]S(z)$, since $A(z^i)$ contributes $a_{n/i}/i$ to $[z^n]$ exactly when $i\mid n$.
\end{definition}

\begin{theorem}[Divisor bridge]\label{thm:divbridge}
For every sequence $a$ and every $n$,
\[
n\,s_n=\omega_n,\qquad\text{i.e.}\qquad n\sum_{i\mid n}\frac{a_{n/i}}{i}=\sum_{d\mid n}d\,a_d .
\]
\end{theorem}

\begin{proof}
The map $i\mapsto n/i$ is an involution of the divisors of $n$; under it the term $n\,a_{n/i}/i$ becomes $n\,a_d/(n/d)=d\,a_d$ with $d=n/i$. Summing gives the claim.
\end{proof}

This single line is the mathematical content of the bridge: it connects the analytic object $S$ to the number-theoretic weight $\omega$. Since $[z^n](zS'(z))=n\,[z^n]S(z)$, Theorem~\ref{thm:divbridge} says exactly that the coefficients of $zS'$ are the divisor weights.

\begin{theorem}[Equivalence of the functional equation and the recurrence]\label{thm:equiv}
For a sequence $a$, the coefficientwise form of (LD),
\[
n\,a_n = a_n + \sum_{j=1}^{n-1}a_j\bigl((n-j)s_{n-j}\bigr)\qquad (n\ge1),
\]
holds if and only if
\[
(k-1)\,a_k=\sum_{j=1}^{k-1}a_j\,\omega_{k-j}\qquad (k\ge2).
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:divbridge} applied termwise the two convolution sums are literally equal. Given the first identity at $n=k\ge2$, subtract $a_k$; conversely add $a_n$. For $n=1$ the first identity reads $a_1=a_1$ plus an empty sum, and is automatic --- which is why the recurrence begins at $k=2$.
\end{proof}

\begin{theorem}[P\'olya tree recurrence]
If $a_1=1$ and the coefficientwise form of (LD) holds for all $n\ge1$, then $a_1=1$ and for every $k\ge2$
\[
a_k=\frac{1}{k-1}\sum_{j=1}^{k-1}a_j\,\omega_{k-j},\qquad \omega_m=\sum_{d\mid m}d\,a_d .
\]
\end{theorem}

\begin{proof}
Theorem~\ref{thm:equiv} gives $(k-1)a_k=\sum_j a_j\omega_{k-j}$, and $k-1\ne0$ since $k\ge2$.
\end{proof}

Together with $a_0=0$, $a_1=1$ this determines the sequence uniquely, and it is the algorithm used in practice: sieve the weights in $O(n\log n)$, then convolve in $O(n^2)$. Two remarks make the parallel with the Fourier story precise. The divisor weight $\omega_n$, which looks like an ad hoc modelling choice, is \emph{forced}: it is $n[z^n]S(z)$, nothing more. And the passage from structure to computation is an \emph{equivalence}, not merely an implication.

\section{Discussion}

Three reasons the categorical framing is not decoration.

\emph{It separates content from bookkeeping.} Everything in Sections~\ref{sec:transform}--7 reduces to the two orthogonality relations of Lemma~\ref{lem:orth}; the categorical apparatus is precisely what makes those relations natural, i.e.\ simultaneously compatible with all homomorphisms --- a compatibility used daily under the names aliasing, periodisation and downsampling.

\emph{It predicts the right generalisations.} The Fourier kernel is the swap of the identity in a self-adjoint duality, a description meaningful in any self-dual setting; the exponential is not the essential ingredient.

\emph{It relocates the uncertainty principle.} Theorem~\ref{thm:abs} shows the principle belongs to any bounded pair of analysis and synthesis kernels, the group order being a reciprocal coherence product. This is the conceptual reason the Donoho--Stark and Elad--Bruckstein bounds look identical: they are the same theorem.

The results also delimit the uncertainty spectrum on $\Z/N$ for odd $N$: modulated coset indicators attain the minimum $N$, quadratic phases the maximum $N^2$, and in between Theorem~\ref{thm:div} imposes an arithmetic constraint. Everything here is finite; the passage to locally compact abelian groups requires Haar measure, a topology on the dual, and continuity of bicharacters, none of which is developed.

\section*{Future directions}
\addcontentsline{toc}{section}{Future directions}

\begin{itemize}
\item \textbf{Beyond finiteness.} Establish the self-adjunction for locally compact abelian groups, with $\Hom$ in topological abelian groups; the bicharacter swap should remain the hom-set bijection, the analytic input being joint continuity of bicharacters.
\item \textbf{Coherence-optimal frames.} Classify flat kernels admitting a bounded inversion with $\mu\nu|H|=1$; conjecturally these are exactly the complex Hadamard matrices up to scaling, an extremals theorem parallel to Theorem~\ref{thm:rigid}.
\item \textbf{Rigidity for general kernels.} For which kernels does equality in Theorem~\ref{thm:abs} force coset structure? Conjecturally the phase-alignment step survives whenever the kernel is flat and the reconstruction is adjoint.
\item \textbf{Non-abelian analogues.} Replacing $\dual G$ by irreducible representations destroys the duality, but Theorem~\ref{thm:abs} does not use group structure and should yield a bound with $\mu$ the largest matrix-entry modulus.
\item \textbf{Arithmetic of extremality.} Theorem~\ref{thm:div} makes extremality divisor-theoretic; count the extremal functions on $\Z/N$ up to scaling, indexed by triples (subgroup, coset, character).
\item \textbf{P\'olya-type bridges.} Identify the general mechanism: for which multiset-substitution schemes does logarithmic differentiation produce an exp-free identity whose coefficients are divisor sums?
\end{itemize}

